def set_left_most_unset_bit(n):
    """Set the leftmost unset bit in the binary representation of n."""
    if n < 0:
        raise ValueError("n must be non-negative")

    width = n.bit_length()
    zero_mask = (~n) & ((1 << width) - 1)

    if zero_mask == 0:
        return n | (1 << width)

    return n | (1 << (zero_mask.bit_length() - 1))


