def magic_square_test(matrix):
    """
    Return True if the given matrix is a magic square.

    A matrix is treated as a magic square if it is square and the sums of
    all rows, all columns, and both main diagonals are equal.
    """
    try:
        rows = [list(row) for row in matrix]
    except TypeError:
        return False

    n = len(rows)
    if n == 0:
        return False

    if any(len(row) != n for row in rows):
        return False

    try:
        target = sum(rows[0])

        for row in rows:
            if sum(row) != target:
                return False

        for col in range(n):
            if sum(row[col] for row in rows) != target:
                return False

        if sum(rows[i][i] for i in range(n)) != target:
            return False

        if sum(rows[i][n - 1 - i] for i in range(n)) != target:
            return False
    except (TypeError, IndexError):
        return False

    return True


assert magic_square_test(
