from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        window_counts = {x: 0 for x in set(nums)}

        for start in range(n - k + 1):
            for x in set(nums[start:start + k]):
                window_counts[x] += 1

        answer = -1
        for x, count in window_counts.items():
            if count == 1 and x > answer:
                answer = x

        return answer
