from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums[0], nums[1])

        INF = 10**18

        # After the first operation, one of nums[0], nums[1], nums[2] remains.
        # dp[f] = minimum cost so far when nums[f] is the current first element
        # and the next not-yet-processed original index is p.
        dp = {
            0: max(nums[1], nums[2]),  # remove nums[1] and nums[2]
            1: max(nums[0], nums[2]),  # remove nums[0] and nums[2]
            2: max(nums[0], nums[1]),  # remove nums[0] and nums[1]
        }

        p = 3

        while p <= n:
            # One element remains: nums[f].
            if p == n:
                return min(cost + nums[f] for f, cost in dp.items())

            # Two elements remain: nums[f] and nums[p].
            if p == n - 1:
                return min(cost + max(nums[f], nums[p]) for f, cost in dp.items())

            a = nums[p]
            b = nums[p + 1]
            ab = max(a, b)
            ndp = {}

            for f, cost in dp.items():
                vf = nums[f]

                # Remove f and a, survivor is b.
                nf = p + 1
                nc = cost + max(vf, a)
                if nc < ndp.get(nf, INF):
                    ndp[nf] = nc

                # Remove f and b, survivor is a.
                nf = p
                nc = cost + max(vf, b)
                if nc < ndp.get(nf, INF):
                    ndp[nf] = nc

                # Remove a and b, survivor is f.
                nf = f
                nc = cost + ab
                if nc < ndp.get(nf, INF):
                    ndp[nf] = nc

            dp = ndp
            p += 2

        return 0
