from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online = [True] * numberOfUsers
        offline_until = [0] * numberOfUsers

        events.sort(key=lambda event: int(event[1]))

        i = 0
        n = len(events)

        while i < n:
            current_time = int(events[i][1])

            # Process automatic online status changes before messages at this timestamp.
            for user in range(numberOfUsers):
                if not online[user] and offline_until[user] <= current_time:
                    online[user] = True
                    offline_until[user] = 0

            j = i
            while j < n and int(events[j][1]) == current_time:
                if events[j][0] == "OFFLINE":
                    user_id = int(events[j][2])
                    online[user_id] = False
                    offline_until[user_id] = current_time + 60
                j += 1

            # Process all MESSAGE events at this timestamp after status changes.
            for k in range(i, j):
                if events[k][0] == "MESSAGE":
                    for token in events[k][2].split():
                        if token == "ALL":
                            for user in range(numberOfUsers):
                                mentions[user] += 1
                        elif token == "HERE":
                            for user in range(numberOfUsers):
                                if online[user]:
                                    mentions[user] += 1
                        elif token.startswith("id"):
                            user_id = int(token[2:])
                            mentions[user_id] += 1

            i = j

        return mentions
