class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def substrings(x: str):
            res = [("", 0)]
            for i in range(len(x)):
                for j in range(i + 1, len(x) + 1):
                    sub = x[i:j]
                    res.append((sub, len(sub)))
            return res

        s_subs = substrings(s)
        t_subs = substrings(t)
        ans = 0
        max_t_len = len(t)

        for a, la in s_subs:
            if la + max_t_len <= ans:
                continue
            for b, lb in t_subs:
                total = la + lb
                if total <= ans:
                    continue
                cand = a + b
                if cand == cand[::-1]:
                    ans = total

        return ans
