from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        should_visit = True

        for row_idx, row in enumerate(grid):
            if row_idx % 2 == 0:
                cells = row
            else:
                cells = reversed(row)

            for value in cells:
                if should_visit:
                    result.append(value)
                should_visit = not should_visit

        return result
