from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []
        if not elements:
            return [-1] * len(groups)

        max_group = max(groups)
        INF = len(elements)

        first_index = [INF] * (max_group + 1)
        present = []

        for idx, value in enumerate(elements):
            if 1 <= value <= max_group and first_index[value] == INF:
                first_index[value] = idx
                present.append(value)

        best = [INF] * (max_group + 1)

        for value in present:
            idx = first_index[value]
            for multiple in range(value, max_group + 1, value):
                if idx < best[multiple]:
                    best[multiple] = idx

        return [best[group] if best[group] != INF else -1 for group in groups]
