from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        ans = total_k

        # If we add x to a subarray, only values equal to k - x inside
        # can become k. Try every value that actually appears in nums.
        for target in set(nums):
            if target == k:
                continue

            current = 0
            best_gain = 0

            for num in nums:
                if num == target:
                    current += 1
                if num == k:
                    current -= 1

                if current < 0:
                    current = 0
                elif current > best_gain:
                    best_gain = current

            ans = max(ans, total_k + best_gain)

        return ans
